-- Data-only sharing contracts. No UI, SavedVariables writes or Lua evaluation.
APR.PathSharingProtocol = {}
local P = APR.PathSharingProtocol
P.PREFIX, P.VERSION = "APRPathV1", 1
P.MAX_BYTES, P.MAX_ROUTES, P.CHUNK = 524288, 256, 140
P.IDLE_TTL, P.TTL = 120, 900

function P.Integer(value, minimum, maximum)
    return type(value) == "number" and value == value and value % 1 == 0
        and value >= minimum and value <= maximum
end--[[APR_DIAG]]; P.Integer = APRTrace("APR-Core/features/group/PathSharingProtocol.lua:13:P.Integer#1", P.Integer)--[[/APR_DIAG]]

function P.Text(value, limit)
    return type(value) == "string" and #value > 0 and #value <= (limit or 240)
        and not value:find("[%z\001-\031]")
end--[[APR_DIAG]]; P.Text = APRTrace("APR-Core/features/group/PathSharingProtocol.lua:18:P.Text#2", P.Text)--[[/APR_DIAG]]

function P.Array(value, maximum)
    if type(value) ~= "table" or #value > maximum then return false end
    local count = 0
    for key in pairs(value) do
        if not P.Integer(key, 1, #value) then return false end
        count = count + 1
    end
    return count == #value
end--[[APR_DIAG]]; P.Array = APRTrace("APR-Core/features/group/PathSharingProtocol.lua:23:P.Array#3", P.Array)--[[/APR_DIAG]]

-- Bound work before copying, serializing or exposing a definition to the engine.
function P.Data(value)
    local active, nodes, bytes = {}, 0, 0
    local function visit(item, depth)
        nodes = nodes + 1
        if nodes > 100000 or depth > 32 then return false end
        local kind = type(item)
        if kind == "string" then
            bytes = bytes + #item
            return bytes <= P.MAX_BYTES and not item:find("%z")
        elseif kind == "number" then
            return item == item and item > -math.huge and item < math.huge
        elseif kind == "boolean" then
            return true
        elseif kind ~= "table" or getmetatable(item) or active[item] then
            return false
        end
        active[item] = true
        for key, child in pairs(item) do
            if type(key) ~= "string" and type(key) ~= "number" then return false end
            if not visit(key, depth + 1) or not visit(child, depth + 1) then return false end
        end
        active[item] = nil
        return true
    end--[[APR_DIAG]]; visit = APRTrace("APR-Core/features/group/PathSharingProtocol.lua:36:visit#5", visit)--[[/APR_DIAG]]
    return visit(value, 0)
end--[[APR_DIAG]]; P.Data = APRTrace("APR-Core/features/group/PathSharingProtocol.lua:34:P.Data#4", P.Data)--[[/APR_DIAG]]

function P.Copy(value)
    if type(value) ~= "table" then return value end
    local result = {}
    for key, child in pairs(value) do result[key] = P.Copy(child) end
    return result
end--[[APR_DIAG]]; P.Copy = APRTrace("APR-Core/features/group/PathSharingProtocol.lua:61:P.Copy#6", P.Copy)--[[/APR_DIAG]]

function P.Equal(left, right)
    if type(left) ~= type(right) then return false end
    if type(left) ~= "table" then return left == right end
    for key, value in pairs(left) do if not P.Equal(value, right[key]) then return false end end
    for key in pairs(right) do if left[key] == nil then return false end end
    return true
end--[[APR_DIAG]]; P.Equal = APRTrace("APR-Core/features/group/PathSharingProtocol.lua:68:P.Equal#7", P.Equal)--[[/APR_DIAG]]

function P.Dependencies(route)
    local result, seen = {}, {}
    local function add(key)
        if P.Text(key) and not seen[key] then result[#result + 1], seen[key] = key, true end
    end--[[APR_DIAG]]; add = APRTrace("APR-Core/features/group/PathSharingProtocol.lua:78:add#9", add)--[[/APR_DIAG]]
    if type(route.requiredRoute) == "string" then add(route.requiredRoute)
    elseif type(route.requiredRoute) == "table" then for _, key in ipairs(route.requiredRoute) do add(key) end end
    return result
end--[[APR_DIAG]]; P.Dependencies = APRTrace("APR-Core/features/group/PathSharingProtocol.lua:76:P.Dependencies#8", P.Dependencies)--[[/APR_DIAG]]

local arrayFields, numberFields, boolFields, tableFields = {}, {}, {}, {}
for name in ("Done DoneDB PickUp PickUpDB QpartDB WaypointDB LeaveQuests GossipOptionIDs Zones OnlyInZones SkipInZones IsQuestsCompleted IsQuestsUncompleted IsQuestsCompletedOnAccount IsQuestsUncompletedOnAccount IsOneOfQuestsCompleted IsOneOfQuestsUncompleted IsOneOfQuestsCompletedOnAccount IsOneOfQuestsUncompletedOnAccount"):gmatch("%S+") do arrayFields[name] = true end
for name in ("ChromiePick DropQuest ExitTutorial GetFP GroupTask LearnProfession LeaveQuest NpcDismount SetHS UseDalaHS UseFlightPath UseGarrisonHS UseHS WarMode Waypoint DenyNPC MerchantNPC SpellTrigger NodeID QuestLineSkip ExtraLine Gossip Brewery SparringRing Range ETA EmoteETA GossipETA Level MinLevel MaxLevel SkipForLvl BeLvl HasAchievement DontHaveAchievement HasAura DontHaveAura HasSpell IsQuestOnQuest IsQuestNotOnQuest IsQuestCompleted IsQuestUncompleted"):gmatch("%S+") do numberFields[name] = true end
for name in ("Bloodlust Boat Tram Zeppelin DeathSkip Dontskipvid ExtraActionB InstanceQuest IsAdventureMap IsCampaignQuest MountVehicle NoArrow NoAutoFlightMap NoAutoAccept NoAutoTurnIn NonSkippableWaypoint ResetRoute RouteCompleted SingleWaypointDisplayDistance SpecialETAHide UseGlider UseHSIfAvailable VehicleExit Hardcore AlliedRace"):gmatch("%S+") do boolFields[name] = true end
for name in ("Qpart QpartPart Fillers Coords MapMarkers Money VendorMoney ItemCount Collection Skill ReputationLevel SkipForReputation ZoneStepTrigger TakePortal TakeBoat TakeZeppelin TakeTram UseItem UseSpell BuyItem BuyMerchant BuyRecipe LearnSkill TrainSkill TrainSpell CraftItem CraftRecipe AnyOf AllOf Not"):gmatch("%S+") do tableFields[name] = true end

local flexibleFields = {}
flexibleFields.Coord = true
flexibleFields.Dungeon = true
flexibleFields.Group = true
-- Level profiles can be names or absolute-XP targets as well as numbers.
for _, field in ipairs({ "Level", "MinLevel", "MaxLevel", "SkipForLvl" }) do
    numberFields[field], flexibleFields[field] = nil, true
end
for name in ("Achievement BankDeposit BankWithdraw BeLvl Buffs Button Class ClassNot ClassSpec DestroyItems DoScenario DontHaveSpell DroppableQuest Emote EnterInstance EnterScenario EquipItem EquippedItem EquippedItemStat Event Faction FillerPreviewImages Gender Grind InVehicle InterfaceVersion InterfaceVersionExact IsQuestReadyForTurnIn ItemTarget KillNPC LeaveInstance LeaveScenario LootItems LootMoney Name Note PickedLoa PreviewImages Race RaidIcon Repair Reputation Scenario SellItems SkillGoal SkipForPrimaryProfessions SkipIfCooldown SpellButton SpellETA TameBeast Treasure Zone _comment _index"):gmatch("%S+") do flexibleFields[name] = true end

local function TextList(value)
    if type(value) == "string" then return true end
    if not P.Array(value, 10000) then return false end
    for _, text in ipairs(value) do if type(text) ~= "string" then return false end end
    return true
end--[[APR_DIAG]]; TextList = APRTrace("APR-Core/features/group/PathSharingProtocol.lua:102:TextList#10", TextList)--[[/APR_DIAG]]

-- Nested action IDs and amounts must not reach native APIs as strings/tables.
local numericMembers = {}
for name in ("x y mapID instanceID npcID itemID spellID questID itemSpellID factionID achievementID criteriaID criteriaIndex scenarioID stepID skillID copper quantity rank count seconds slot precision minDurability reserveCopper bagSlots objectiveIndex Number Qid MobId spellId"):gmatch("%S+") do numericMembers[name] = true end
local function Members(data)
    for key, value in pairs(data) do
        if numericMembers[key] and type(value) ~= "number" then return false end
        if (key == "text" or key == "Text" or key == "operator" or key == "dungeonKey" or key == "entranceID")
            and type(value) ~= "string" then return false end
        if type(value) == "table" and not Members(value) then return false end
    end
    return true
end--[[APR_DIAG]]; Members = APRTrace("APR-Core/features/group/PathSharingProtocol.lua:112:Members#11", Members)--[[/APR_DIAG]]

local requiredMembers = {
    UseItem = { "itemID" }, UseSpell = { "spellID" }, Treasure = { "questID" },
    Achievement = { "achievementID" }, KillNPC = { "npcID", "name" },
    Scenario = { "scenarioID", "stepID", "criteriaID", "criteriaIndex" },
    Group = { "questID", "Number" }, DroppableQuest = { "Qid", "MobId", "Text" },
    EquipItem = { "itemID", "slot" }, Repair = { "npcID" }, SkillGoal = { "skillID", "rank" },
    Reputation = { "factionID", "level" }, ReputationLevel = { "factionID", "level" },
    SkipForReputation = { "factionID", "level" }, SpellETA = { "seconds" }, Emote = { "emote" },
}

local function ActionShape(key, value)
    local required = requiredMembers[key]
    if required then
        if type(value) ~= "table" then return false end
        for _, member in ipairs(required) do if value[member] == nil then return false end end
        if key == "KillNPC" and type(value.name) ~= "string" then return false end
        if key == "Emote" and type(value.emote) ~= "string" then return false end
        if key == "SpellETA" and not (value.spellID or value.itemID) then return false end
    end
    if key == "Qpart" or key == "QpartPart" or key == "Fillers" then
        if type(value) ~= "table" then return false end
        for id, objectives in pairs(value) do
            if not P.Integer(id, 1, 100000000) or not P.Array(objectives, 10000) then return false end
            for _, objective in ipairs(objectives) do if not P.Integer(objective, 1, 100000000) then return false end end
        end
    elseif key == "BuyMerchant" or key == "LootItems" or key == "Buffs" then
        if not P.Array(value, 10000) then return false end
        for _, entry in ipairs(value) do
            if type(entry) ~= "table" or not entry[key == "Buffs" and "spellId" or "itemID"] then return false end
        end
    elseif key == "PreviewImages" then
        if not P.Array(value, 1000) or not TextList(value) then return false end
    elseif key == "Level" or key == "MinLevel" or key == "MaxLevel" or key == "SkipForLvl" or key == "Grind" then
        if type(value) ~= "number" and type(value) ~= "string"
            and not (type(value) == "table" and type(value.level) == "number" and type(value.xp) == "number") then return false end
    end
    return true
end--[[APR_DIAG]]; ActionShape = APRTrace("APR-Core/features/group/PathSharingProtocol.lua:132:ActionShape#12", ActionShape)--[[/APR_DIAG]]

local function Steps(steps)
    if not P.Array(steps, 10000) then return false end
    for _, step in ipairs(steps) do
        if type(step) ~= "table" then return false end
        -- Scenario blocks have their own ordered step arrays.
        if step.steps then
            if not Steps(step.steps) then return false end
        else
            for key, value in pairs(step) do
                if type(key) ~= "string" then return false end
                if not ActionShape(key, value) then return false end
                if not arrayFields[key] and not numberFields[key] and not boolFields[key] and not tableFields[key]
                    and not flexibleFields[key] and not key:match("^ExtraLineText%d*$") and not key:match("^TrigText%d*$") then return false end
                if arrayFields[key] then
                    if not P.Array(value, 10000) then return false end
                    for _, id in ipairs(value) do if not P.Integer(id, 1, 100000000) then return false end end
                elseif numberFields[key] and type(value) ~= "number" then return false
                elseif boolFields[key] and type(value) ~= "boolean" then return false
                elseif tableFields[key] and type(value) ~= "table" then return false
                elseif (key == "Name" or key == "_comment" or key == "Dungeon") and type(value) ~= "string" then return false
                elseif key == "Coord" then
                    if type(value) ~= "table" then return false end
                    if value.x ~= nil or value.y ~= nil then
                        if type(value.x) ~= "number" or type(value.y) ~= "number" then return false end
                    elseif not P.Array(value, 10000) then return false end
                elseif key == "Note" or key:match("^ExtraLineText%d*$") then
                    if not TextList(value) then return false end
                elseif key:match("^TrigText%d*$") and type(value) ~= "string" then return false
                end
                if type(value) == "table" and not Members(value) then return false end
            end
        end
    end
    return true
end--[[APR_DIAG]]; Steps = APRTrace("APR-Core/features/group/PathSharingProtocol.lua:161:Steps#13", Steps)--[[/APR_DIAG]]

function P.Definition(data)
    if type(data) ~= "table" or not P.Data(data) then return false end
    if not data.steps and not data.scenarios then return #data > 0 and Steps(data) end
    if data.label ~= nil and not P.Text(data.label) then return false end
    if data.conditions ~= nil and type(data.conditions) ~= "table" then return false end
    if not Members(data) then return false end
    if data.requiredRoute ~= nil then
        local required = type(data.requiredRoute) == "string" and { data.requiredRoute } or data.requiredRoute
        if not P.Array(required, P.MAX_ROUTES) then return false end
        for _, key in ipairs(required) do if not P.Text(key) then return false end end
    end
    if data.nextRoute ~= nil then
        if not P.Array(data.nextRoute, P.MAX_ROUTES) then return false end
        for _, entry in ipairs(data.nextRoute) do
            if not P.Text(entry) and not (type(entry) == "table" and P.Text(entry.route)
                and (entry.conditions == nil or type(entry.conditions) == "table")) then return false end
        end
    end
    if data.parallelSteps then
        if not P.Array(data.parallelSteps, 1000) then return false end
        for _, group in ipairs(data.parallelSteps) do
            if type(group) ~= "table" or not Steps(group.steps) then return false end
        end
    end
    return Steps(data.steps or data.scenarios)
end--[[APR_DIAG]]; P.Definition = APRTrace("APR-Core/features/group/PathSharingProtocol.lua:197:P.Definition#14", P.Definition)--[[/APR_DIAG]]

function P.Packet(packet)
    if type(packet) ~= "table" or not P.Data(packet) or packet.v ~= P.VERSION
        or (packet.kind ~= "path" and packet.kind ~= "route") or not P.Text(packet.client, 40)
        or not P.Array(packet.path, P.MAX_ROUTES) or #packet.path == 0
        or not P.Array(packet.routes, P.MAX_ROUTES) or #packet.routes == 0 then return false end
    local records = {}
    for _, record in ipairs(packet.routes) do
        if type(record) ~= "table" or not P.Text(record.key) or not P.Text(record.label)
            or records[record.key] or type(record.custom) ~= "boolean"
            or not P.Array(record.required, P.MAX_ROUTES) then return false end
        if record.custom and not P.Definition(record.data) or not record.custom and record.data ~= nil then return false end
        for _, key in ipairs(record.required) do if not P.Text(key) then return false end end
        if record.custom and not P.Equal(record.required, P.Dependencies(record.data)) then return false end
        records[record.key] = record
    end
    for _, key in ipairs(packet.path) do if not records[key] then return false end end
    for _, record in ipairs(packet.routes) do
        for _, key in ipairs(record.required) do if not records[key] then return false end end
    end
    if packet.kind == "route" and (#packet.path ~= 1 or not records[packet.path[1]].custom) then return false end
    if packet.position ~= nil then
        local pos = packet.position
        if type(pos) ~= "table" or not records[pos.route] or not P.Text(pos.id, 80)
            or not P.Text(pos.fingerprint, 100) then return false end
    end
    return true
end--[[APR_DIAG]]; P.Packet = APRTrace("APR-Core/features/group/PathSharingProtocol.lua:224:P.Packet#15", P.Packet)--[[/APR_DIAG]]
